-- DRAFT IMPLEMENTATION SPECIFICATION — do not apply to production without review.
-- Bible Study Repo / Scripture foundation / migration 0001
-- Target dialect: SQLite compatible with Cloudflare D1.
-- Stable IDs are generated by the application, not by SQLite rowids.

CREATE TABLE scriptural_works (
  id TEXT PRIMARY KEY NOT NULL,
  osis_code TEXT NOT NULL UNIQUE,
  standard_name TEXT NOT NULL,
  testament TEXT NOT NULL CHECK (testament IN ('old', 'new')),
  genre TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE canons (
  id TEXT PRIMARY KEY NOT NULL,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  tradition_label TEXT,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('draft', 'active', 'retired')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE canon_books (
  id TEXT PRIMARY KEY NOT NULL,
  canon_id TEXT NOT NULL,
  work_id TEXT NOT NULL,
  position INTEGER NOT NULL CHECK (position > 0),
  display_name TEXT NOT NULL,
  is_included INTEGER NOT NULL DEFAULT 1 CHECK (is_included IN (0, 1)),
  FOREIGN KEY (canon_id) REFERENCES canons(id) ON DELETE RESTRICT,
  FOREIGN KEY (work_id) REFERENCES scriptural_works(id) ON DELETE RESTRICT,
  UNIQUE (canon_id, work_id),
  UNIQUE (canon_id, position)
);

CREATE TABLE versification_schemes (
  id TEXT PRIMARY KEY NOT NULL,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  description TEXT,
  version TEXT,
  source_note TEXT,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'verified', 'retired')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE scheme_chapters (
  id TEXT PRIMARY KEY NOT NULL,
  scheme_id TEXT NOT NULL,
  work_id TEXT NOT NULL,
  chapter_label TEXT NOT NULL,
  chapter_order INTEGER NOT NULL CHECK (chapter_order > 0),
  FOREIGN KEY (scheme_id) REFERENCES versification_schemes(id) ON DELETE RESTRICT,
  FOREIGN KEY (work_id) REFERENCES scriptural_works(id) ON DELETE RESTRICT,
  UNIQUE (id, scheme_id, work_id),
  UNIQUE (scheme_id, work_id, chapter_order),
  UNIQUE (scheme_id, work_id, chapter_label)
);

CREATE TABLE scripture_units (
  id TEXT PRIMARY KEY NOT NULL,
  scheme_id TEXT NOT NULL,
  work_id TEXT NOT NULL,
  chapter_id TEXT NOT NULL,
  unit_label TEXT NOT NULL,
  unit_order INTEGER NOT NULL CHECK (unit_order > 0),
  unit_kind TEXT NOT NULL DEFAULT 'verse'
    CHECK (unit_kind IN ('verse', 'heading', 'superscription', 'other')),
  FOREIGN KEY (chapter_id, scheme_id, work_id)
    REFERENCES scheme_chapters(id, scheme_id, work_id) ON DELETE RESTRICT,
  UNIQUE (id, scheme_id),
  UNIQUE (id, scheme_id, work_id),
  UNIQUE (scheme_id, work_id, chapter_id, unit_order),
  UNIQUE (scheme_id, work_id, chapter_id, unit_label)
);

CREATE TABLE scripture_unit_mappings (
  id TEXT PRIMARY KEY NOT NULL,
  from_unit_id TEXT NOT NULL,
  from_scheme_id TEXT NOT NULL,
  to_unit_id TEXT NOT NULL,
  to_scheme_id TEXT NOT NULL,
  mapping_type TEXT NOT NULL
    CHECK (mapping_type IN ('equivalent', 'split', 'combined', 'partial', 'approximate')),
  source_id TEXT,
  confidence TEXT NOT NULL DEFAULT 'unreviewed'
    CHECK (confidence IN ('unreviewed', 'high', 'medium', 'low', 'disputed')),
  notes TEXT,
  review_status TEXT NOT NULL DEFAULT 'pending'
    CHECK (review_status IN ('pending', 'approved', 'rejected')),
  created_at INTEGER NOT NULL,
  FOREIGN KEY (from_unit_id, from_scheme_id) REFERENCES scripture_units(id, scheme_id) ON DELETE RESTRICT,
  FOREIGN KEY (to_unit_id, to_scheme_id) REFERENCES scripture_units(id, scheme_id) ON DELETE RESTRICT,
  CHECK (from_unit_id <> to_unit_id),
  CHECK (from_scheme_id <> to_scheme_id)
);

CREATE TABLE translation_editions (
  id TEXT PRIMARY KEY NOT NULL,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  abbreviation TEXT NOT NULL,
  language_tag TEXT NOT NULL,
  publisher TEXT,
  edition_label TEXT,
  publication_year INTEGER,
  versification_scheme_id TEXT NOT NULL,
  rights_status TEXT NOT NULL DEFAULT 'unverified'
    CHECK (rights_status IN ('unverified', 'public_domain_verified', 'licensed', 'restricted', 'withdrawn')),
  rights_notes TEXT,
  source_url TEXT,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'available', 'retired')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (versification_scheme_id) REFERENCES versification_schemes(id) ON DELETE RESTRICT,
  UNIQUE (id, versification_scheme_id)
);

CREATE TABLE translation_texts (
  id TEXT PRIMARY KEY NOT NULL,
  edition_id TEXT NOT NULL,
  versification_scheme_id TEXT NOT NULL,
  scripture_unit_id TEXT NOT NULL,
  text TEXT NOT NULL,
  paragraph_marker TEXT,
  poetry_level INTEGER CHECK (poetry_level IS NULL OR poetry_level >= 0),
  footnote_metadata_json TEXT
    CHECK (footnote_metadata_json IS NULL OR json_valid(footnote_metadata_json)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (edition_id, versification_scheme_id)
    REFERENCES translation_editions(id, versification_scheme_id) ON DELETE RESTRICT,
  FOREIGN KEY (scripture_unit_id, versification_scheme_id)
    REFERENCES scripture_units(id, scheme_id) ON DELETE RESTRICT,
  UNIQUE (edition_id, scripture_unit_id)
);

CREATE TABLE passage_references (
  id TEXT PRIMARY KEY NOT NULL,
  label TEXT NOT NULL,
  reference_scheme_id TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (reference_scheme_id) REFERENCES versification_schemes(id) ON DELETE RESTRICT,
  UNIQUE (id, reference_scheme_id)
);

CREATE TABLE passage_reference_segments (
  id TEXT PRIMARY KEY NOT NULL,
  passage_reference_id TEXT NOT NULL,
  reference_scheme_id TEXT NOT NULL,
  work_id TEXT NOT NULL,
  segment_order INTEGER NOT NULL CHECK (segment_order > 0),
  start_unit_id TEXT NOT NULL,
  end_unit_id TEXT NOT NULL,
  notes TEXT,
  FOREIGN KEY (passage_reference_id, reference_scheme_id)
    REFERENCES passage_references(id, reference_scheme_id) ON DELETE CASCADE,
  FOREIGN KEY (start_unit_id, reference_scheme_id, work_id)
    REFERENCES scripture_units(id, scheme_id, work_id) ON DELETE RESTRICT,
  FOREIGN KEY (end_unit_id, reference_scheme_id, work_id)
    REFERENCES scripture_units(id, scheme_id, work_id) ON DELETE RESTRICT,
  UNIQUE (passage_reference_id, segment_order)
);

CREATE INDEX idx_canon_books_canon_position
  ON canon_books(canon_id, position);

CREATE INDEX idx_scheme_chapters_work_order
  ON scheme_chapters(scheme_id, work_id, chapter_order);

CREATE INDEX idx_scripture_units_reference
  ON scripture_units(scheme_id, work_id, chapter_id, unit_order);

CREATE INDEX idx_scripture_unit_mappings_from
  ON scripture_unit_mappings(from_unit_id, from_scheme_id);

CREATE INDEX idx_scripture_unit_mappings_to
  ON scripture_unit_mappings(to_unit_id, to_scheme_id);

CREATE INDEX idx_translation_texts_edition
  ON translation_texts(edition_id, scripture_unit_id);

CREATE INDEX idx_passage_segments_start
  ON passage_reference_segments(start_unit_id);

CREATE INDEX idx_passage_segments_end
  ON passage_reference_segments(end_unit_id);
